-- public.casting_gate(p_piece text, p_metal text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.casting_gate(p_piece text, p_metal text)
 RETURNS skill_gate
 LANGUAGE sql
 STABLE
AS $function$
  select g.* from mould_def d join metal_def m on lower(m.name) = lower(p_metal)
    join skill_gate g on g.kind = 'casting' and g.id = d.skill || ':' || m.id
   where d.makes = p_piece and d.makes not like '%\_casting'
$function$
